INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass jede Klasse automatisch von Object erbt. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Object ist die Wurzelklasse in Java"}, {"text": "Nein", "correct": false, "because": "Vererbung ist implizit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um eine Methode in einer Unterklasse zu überschreiben?', 3, '[{"text": "@Override", "correct": true, "because": "Markiert überschriebene Methoden"}, {"text": "@Extend", "correct": false, "because": "Gibt es nicht"}, {"text": "@Super", "correct": false, "because": "Falsche Annotation"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Mechanismen nutze ich, um Fehler zu behandeln?', 5, '[{"text": "try-catch", "correct": true, "because": "Fängt Ausnahmen ab"}, {"text": "throws", "correct": true, "because": "Deklariert Ausnahmen"}, {"text": "return", "correct": false, "because": "Beendet nur Methoden"}, {"text": "break", "correct": false, "because": "Für Schleifen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Interfaces können mehrere Klassen implementieren. b) Abstrakte Klassen können keine Instanzen haben.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Interfaces sind mehrfach implementierbar, abstrakte Klassen nicht instanziierbar"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich eine Klasse für eine Liste entwerfe?', 4, '[{"text": "Generics", "correct": false, "because": "Sichert Typsicherheit"}, {"text": "Iterator", "correct": false, "because": "Wichtig für Durchlauf"}, {"text": "Farbschema", "correct": true, "because": "Irrelevant für Funktionalität"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass final-Variablen nachträglich geändert werden können?', 2, '[{"text": "Nein", "correct": true, "because": "final macht Variablen konstant"}, {"text": "Ja", "correct": false, "because": "Konstanten sind unveränderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaft ist für eine effiziente Datenstruktur entscheidend?', 3, '[{"text": "Generics", "correct": true, "because": "Ermöglicht typsicheren Code"}, {"text": "Hohe Taktfrequenz", "correct": false, "because": "Hardware-spezifisch"}, {"text": "Großer Cache", "correct": false, "because": "Nicht softwarebezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ansätze verbessern die Sicherheit von Code?', 5, '[{"text": "Ausnahmenbehandlung", "correct": true, "because": "Verhindert Abstürze"}, {"text": "private Attribute", "correct": true, "because": "Schützt Daten"}, {"text": "Hohe Schleifenanzahl", "correct": false, "because": "Nur Performance-relevant"}, {"text": "Statische Methoden", "correct": false, "because": "Nicht sicherheitsrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Polymorphismus erlaubt Methodenüberladung. b) Überladung ist dasselbe wie Überschreiben. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Überladung und Überschreiben sind unterschiedlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Datenbankverbindung?', 4, '[{"text": "JDBC-Treiber", "correct": false, "because": "Notwendig für Kommunikation"}, {"text": "Connection-URL", "correct": false, "because": "Definiert Ziel"}, {"text": "Farbanpassung", "correct": true, "because": "Irrelevant für Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Arbeiten alle Schleifen gleich schnell?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Bedingung und Daten"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Optimierungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte machen eine Methode robust?', 4, '[{"text": "Parameterprüfung", "correct": true, "because": "Verhindert ungültige Eingaben"}, {"text": "Ausnahmenbehandlung", "correct": true, "because": "Fängt Fehler ab"}, {"text": "Hohe Taktfrequenz", "correct": false, "because": "Hardware-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Klassen ohne Konstruktor nicht laufen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Standardkonstruktor wird generiert"}, {"text": "Ja", "correct": false, "because": "Compiler erstellt Default"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Gestaltung einer Schnittstelle?', 3, '[{"text": "Klar definierte Methoden", "correct": true, "because": "Fördert Verständnis"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Implementierungsdetail"}, {"text": "Viele Parameter", "correct": false, "because": "Komplexität erhöht"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Static-Methoden gehören der Klasse. b) Sie brauchen Instanzen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Static benötigt keine Instanz"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Verwendung von Generics?', 5, '[{"text": "Typsicherheit", "correct": true, "because": "Verhindert Laufzeitfehler"}, {"text": "Wiederverwendbarkeit", "correct": true, "because": "Flexibler Code"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Nicht primär"}, {"text": "Kleinere Dateien", "correct": false, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Schleife unwichtig?', 3, '[{"text": "Bedingungsprüfung", "correct": false, "because": "Steuert Ablauf"}, {"text": "Zähler", "correct": false, "because": "Relevant für Fortschritt"}, {"text": "Farbanpassung", "correct": true, "because": "Kein Einfluss auf Logik"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist synchronized immer für Threads nötig?', 3, '[{"text": "Nein", "correct": true, "because": "Nur bei gemeinsamen Ressourcen"}, {"text": "Ja", "correct": false, "because": "Nicht universell erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich eine Klasse ohne main-Methode starten kann?', 2, '[{"text": "Nein", "correct": true, "because": "main ist Einstiegspunkt"}, {"text": "Ja", "correct": false, "because": "JVM benötigt main"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Option wähle ich, um Daten serialisierbar zu machen?', 4, '[{"text": "implements Serializable���serializable", "correct": true, "because": "Ermöglicht Serialisierung"}, {"text": "extends Stream", "correct": false, "because": "Nicht relevant"}, {"text": "uses Formatter", "correct": false, "because": "Für Formatierung"}]');
